import{_ as n,c as t,o as e,ag as s}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Dynamiska objekt och animationer","description":"","frontmatter":{},"headers":[],"relativePath":"07-hmi-design/dynamiska-objekt.md","filePath":"07-hmi-design/dynamiska-objekt.md","lastUpdated":1768470380000}'),i={name:"07-hmi-design/dynamiska-objekt.md"};function o(r,a,l,p,d,g){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="dynamiska-objekt-och-animationer" tabindex="-1">Dynamiska objekt och animationer <a class="header-anchor" href="#dynamiska-objekt-och-animationer" aria-label="Permalink to &quot;Dynamiska objekt och animationer&quot;">​</a></h1><p><strong>Animationer</strong> gör HMI-skärmar levande och informativa genom att visuellt representera processförändringar i realtid. I WinCC kan du animera färg, storlek, position, synlighet och mycket mer baserat på PLC-värden.</p><h2 id="oversikt-animations" tabindex="-1">Översikt: Animations <a class="header-anchor" href="#oversikt-animations" aria-label="Permalink to &quot;Översikt: Animations&quot;">​</a></h2><p>Varje objekt i WinCC kan ha <strong>animationer</strong> kopplade till egenskaper (properties).</p><h3 id="animerbara-egenskaper" tabindex="-1">Animerbara egenskaper <a class="header-anchor" href="#animerbara-egenskaper" aria-label="Permalink to &quot;Animerbara egenskaper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Egenskap</th><th>Vad animeras</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>Visibility</strong></td><td>Visa/dölj objekt</td><td>Visa larm endast när aktivt</td></tr><tr><td><strong>Background color</strong></td><td>Bakgrundsfärg</td><td>Grön=OK, Röd=Fel</td></tr><tr><td><strong>Position</strong></td><td>X/Y-koordinater</td><td>Flytta ventil-ikon</td></tr><tr><td><strong>Size</strong></td><td>Bredd/höjd</td><td>Växa tank när fylls</td></tr><tr><td><strong>Rotation</strong></td><td>Rotation (grader)</td><td>Roterande motor-ikon</td></tr><tr><td><strong>Flashing</strong></td><td>Blinka</td><td>Blinkandelarm</td></tr><tr><td><strong>Text</strong></td><td>Dynamisk text</td><td>&quot;Running&quot; / &quot;Stopped&quot;</td></tr></tbody></table><h2 id="farganimationer" tabindex="-1">Färganimationer <a class="header-anchor" href="#farganimationer" aria-label="Permalink to &quot;Färganimationer&quot;">​</a></h2><h3 id="background-color-animation" tabindex="-1">Background Color Animation <a class="header-anchor" href="#background-color-animation" aria-label="Permalink to &quot;Background Color Animation&quot;">​</a></h3><p>Den vanligaste animationen - ändra färg baserat på taggvärde.</p><p><strong>Exempel: Motor-status (grön/grå)</strong></p><ol><li>Skapa en <strong>Circle</strong> (motor-indikator)</li><li><strong>Properties</strong> → <strong>Animations</strong></li><li>Klicka <strong>[+]</strong> vid <strong>Appearance</strong></li><li>Välj <strong>Background color</strong></li><li><strong>Tag:</strong> <code>Motor_Running</code> (BOOL)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Type: Binary (2 states)</span></span>
<span class="line"><span>0 (FALSE): Grå (#808080)</span></span>
<span class="line"><span>1 (TRUE): Grön (#00FF00)</span></span></code></pre></div></li></ol><h3 id="multi-state-farganimation" tabindex="-1">Multi-state färganimation <a class="header-anchor" href="#multi-state-farganimation" aria-label="Permalink to &quot;Multi-state färganimation&quot;">​</a></h3><p>För värden med fler än 2 tillstånd (ex: INT).</p><p><strong>Exempel: Process-status</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag: Process_State (INT)</span></span>
<span class="line"><span>0: Grå - Stopped</span></span>
<span class="line"><span>1: Gul - Starting</span></span>
<span class="line"><span>2: Grön - Running</span></span>
<span class="line"><span>3: Orange - Paused</span></span>
<span class="line"><span>4: Röd - Fault</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li><strong>Animations</strong> → <strong>Background color</strong></li><li><strong>Tag:</strong> <code>Process_State</code></li><li><strong>Type:</strong> Range (multiple values)</li><li><strong>Ranges:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0-0: #808080 (Grå)</span></span>
<span class="line"><span>1-1: #FFFF00 (Gul)</span></span>
<span class="line"><span>2-2: #00FF00 (Grön)</span></span>
<span class="line"><span>3-3: #FFA500 (Orange)</span></span>
<span class="line"><span>4-10: #FF0000 (Röd)</span></span></code></pre></div></li></ol><h3 id="gradient-farganimation" tabindex="-1">Gradient färganimation <a class="header-anchor" href="#gradient-farganimation" aria-label="Permalink to &quot;Gradient färganimation&quot;">​</a></h3><p>För analoga värden (temperatur, tryck).</p><p><strong>Exempel: Temperatur-indikator (gradient)</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag: Temperature (REAL, 0-100°C)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0°C: Blå (#0000FF)</span></span>
<span class="line"><span>50°C: Grön (#00FF00)</span></span>
<span class="line"><span>100°C: Röd (#FF0000)</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li><strong>Type:</strong> Linear (gradient)</li><li><strong>Min value:</strong> 0, <strong>Color:</strong> Blå</li><li><strong>Mid value:</strong> 50, <strong>Color:</strong> Grön</li><li><strong>Max value:</strong> 100, <strong>Color:</strong> Röd</li></ol><h2 id="visibility-animation-visa-dolj" tabindex="-1">Visibility Animation (Visa/Dölj) <a class="header-anchor" href="#visibility-animation-visa-dolj" aria-label="Permalink to &quot;Visibility Animation (Visa/Dölj)&quot;">​</a></h2><h3 id="visa-objekt-nar-villkor-uppfyllt" tabindex="-1">Visa objekt när villkor uppfyllt <a class="header-anchor" href="#visa-objekt-nar-villkor-uppfyllt" aria-label="Permalink to &quot;Visa objekt när villkor uppfyllt&quot;">​</a></h3><p><strong>Exempel: Visa larmtext endast när larm aktivt</strong></p><ol><li>Skapa <strong>Text</strong> med &quot;⚠️ ALARM ACTIVE&quot;</li><li><strong>Animations</strong> → <strong>Visibility</strong></li><li><strong>Tag:</strong> <code>Alarm_Active</code> (BOOL)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Type: Binary</span></span>
<span class="line"><span>0 (FALSE): Hidden (osynlig)</span></span>
<span class="line"><span>1 (TRUE): Visible (synlig)</span></span></code></pre></div></li></ol><h3 id="vaxla-mellan-tva-objekt" tabindex="-1">Växla mellan två objekt <a class="header-anchor" href="#vaxla-mellan-tva-objekt" aria-label="Permalink to &quot;Växla mellan två objekt&quot;">​</a></h3><p><strong>Exempel: Visa &quot;START&quot; eller &quot;STOP&quot; beroende på motor-status</strong></p><p><strong>Metod 1: Två objekt</strong></p><ul><li><strong>Text &quot;START&quot;:</strong> Synlig när <code>Motor_Running = FALSE</code></li><li><strong>Text &quot;RUNNING&quot;:</strong> Synlig när <code>Motor_Running = TRUE</code></li></ul><p><strong>Metod 2: Dynamisk text (bättre)</strong></p><ul><li>En text med <strong>text list animation</strong> (se nedan)</li></ul><h2 id="text-animation" tabindex="-1">Text Animation <a class="header-anchor" href="#text-animation" aria-label="Permalink to &quot;Text Animation&quot;">​</a></h2><h3 id="text-list-textlista" tabindex="-1">Text List (Textlista) <a class="header-anchor" href="#text-list-textlista" aria-label="Permalink to &quot;Text List (Textlista)&quot;">​</a></h3><p>Visa olika texter baserat på värde.</p><p><strong>Exempel: Motor-status</strong></p><ol><li>Skapa <strong>Text field</strong></li><li><strong>Animations</strong> → <strong>Text</strong></li><li><strong>Tag:</strong> <code>Motor_State</code> (INT)</li><li><strong>Type:</strong> Text list</li><li><strong>Text list:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0: &quot;Stopped&quot;</span></span>
<span class="line"><span>1: &quot;Starting...&quot;</span></span>
<span class="line"><span>2: &quot;Running&quot;</span></span>
<span class="line"><span>3: &quot;Stopping...&quot;</span></span>
<span class="line"><span>4: &quot;Fault&quot;</span></span></code></pre></div></li></ol><h3 id="dynamisk-text-med-varde" tabindex="-1">Dynamisk text med värde <a class="header-anchor" href="#dynamisk-text-med-varde" aria-label="Permalink to &quot;Dynamisk text med värde&quot;">​</a></h3><p><strong>Exempel: Visa hastighet i text</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Text: &quot;Motor speed: [Motor_Speed] rpm&quot;</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li>Text field</li><li><strong>Text:</strong> &quot;Motor speed: &quot;</li><li>Lägg till <strong>I/O field</strong> bredvid med tagg <code>Motor_Speed</code></li></ol><h2 id="position-animation" tabindex="-1">Position Animation <a class="header-anchor" href="#position-animation" aria-label="Permalink to &quot;Position Animation&quot;">​</a></h2><h3 id="flytta-objekt-baserat-pa-varde" tabindex="-1">Flytta objekt baserat på värde <a class="header-anchor" href="#flytta-objekt-baserat-pa-varde" aria-label="Permalink to &quot;Flytta objekt baserat på värde&quot;">​</a></h3><p><strong>Exempel: Ventil öppnas (rör sig från vänster till höger)</strong></p><ol><li>Skapa <strong>Rectangle</strong> (ventil-symbolisering)</li><li><strong>Animations</strong> → <strong>Position</strong></li><li><strong>Tag:</strong> <code>Valve_Position</code> (INT, 0-100%)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Type: Linear</span></span>
<span class="line"><span>Tag value 0: X = 100 px</span></span>
<span class="line"><span>Tag value 100: X = 300 px</span></span></code></pre></div></li></ol><p><strong>Resultat:</strong> När <code>Valve_Position</code> = 50, är ventilen på X=200 px (mitten).</p><h3 id="tank-niva-vertikal-position" tabindex="-1">Tank-nivå (vertikal position) <a class="header-anchor" href="#tank-niva-vertikal-position" aria-label="Permalink to &quot;Tank-nivå (vertikal position)&quot;">​</a></h3><p><strong>Exempel: Vätska i tank</strong></p><ol><li>Skapa <strong>Rectangle</strong> (blå, representerar vätska)</li><li>Placera i botten av tank-ikon</li><li><strong>Animations</strong> → <strong>Size</strong> → <strong>Height</strong></li><li><strong>Tag:</strong> <code>Tank_Level</code> (REAL, 0-100%)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Type: Linear</span></span>
<span class="line"><span>0: Height = 0 px</span></span>
<span class="line"><span>100: Height = 200 px</span></span></code></pre></div></li></ol><h2 id="rotation-animation" tabindex="-1">Rotation Animation <a class="header-anchor" href="#rotation-animation" aria-label="Permalink to &quot;Rotation Animation&quot;">​</a></h2><h3 id="roterande-motor-pump" tabindex="-1">Roterande motor/pump <a class="header-anchor" href="#roterande-motor-pump" aria-label="Permalink to &quot;Roterande motor/pump&quot;">​</a></h3><p><strong>Exempel: Motor roterar när igång</strong></p><ol><li>Skapa <strong>Circle</strong> med pil (motor-ikon)</li><li><strong>Animations</strong> → <strong>Rotation</strong></li><li><strong>Tag:</strong> <code>Motor_Running</code> (BOOL)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Type: Continuous rotation</span></span>
<span class="line"><span>Speed: 360° per sekund (1 varv/s)</span></span>
<span class="line"><span>Direction: Clockwise</span></span>
<span class="line"><span>Condition: Motor_Running = TRUE</span></span></code></pre></div></li></ol><h3 id="rotation-baserat-pa-hastighet" tabindex="-1">Rotation baserat på hastighet <a class="header-anchor" href="#rotation-baserat-pa-hastighet" aria-label="Permalink to &quot;Rotation baserat på hastighet&quot;">​</a></h3><p><strong>Exempel: Snabbare rotation vid högre hastighet</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag: Motor_Speed (INT, 0-1500 rpm)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0 rpm: 0°/s (ingen rotation)</span></span>
<span class="line"><span>1500 rpm: 720°/s (2 varv/s)</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li><strong>Type:</strong> Speed-controlled</li><li><strong>Speed calculation:</strong> <code>(Motor_Speed / 1500) * 720</code></li></ol><h2 id="size-animation-storlek" tabindex="-1">Size Animation (Storlek) <a class="header-anchor" href="#size-animation-storlek" aria-label="Permalink to &quot;Size Animation (Storlek)&quot;">​</a></h2><h3 id="vaxa-krympa-objekt" tabindex="-1">Växa/krympa objekt <a class="header-anchor" href="#vaxa-krympa-objekt" aria-label="Permalink to &quot;Växa/krympa objekt&quot;">​</a></h3><p><strong>Exempel: Progressbar för produktion</strong></p><ol><li>Skapa <strong>Rectangle</strong></li><li><strong>Animations</strong> → <strong>Size</strong> → <strong>Width</strong></li><li><strong>Tag:</strong> <code>Production_Progress</code> (INT, 0-100%)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0: Width = 0 px</span></span>
<span class="line"><span>100: Width = 400 px</span></span></code></pre></div></li></ol><h3 id="pulsande-varning" tabindex="-1">Pulsande varning <a class="header-anchor" href="#pulsande-varning" aria-label="Permalink to &quot;Pulsande varning&quot;">​</a></h3><p><strong>Exempel: Larm-ikon växer/krymper</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag: Alarm_Active (BOOL)</span></span>
<span class="line"><span>Condition: TRUE → Pulse between 50-100% size</span></span></code></pre></div><h2 id="flashing-blinkande" tabindex="-1">Flashing (Blinkande) <a class="header-anchor" href="#flashing-blinkande" aria-label="Permalink to &quot;Flashing (Blinkande)&quot;">​</a></h2><h3 id="enkel-blinkning" tabindex="-1">Enkel blinkning <a class="header-anchor" href="#enkel-blinkning" aria-label="Permalink to &quot;Enkel blinkning&quot;">​</a></h3><p><strong>Exempel: Kritiskt larm blinkar rött</strong></p><ol><li>Skapa <strong>Circle</strong> (röd bakgrund)</li><li><strong>Animations</strong> → <strong>Appearance</strong> → <strong>Flashing</strong></li><li><strong>Tag:</strong> <code>Alarm_Critical</code> (BOOL)</li><li><strong>Konfiguration:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Flash frequency: 2 Hz (2 blinkningar/s)</span></span>
<span class="line"><span>Flash when: Alarm_Critical = TRUE</span></span></code></pre></div></li></ol><h3 id="blinkande-text" tabindex="-1">Blinkande text <a class="header-anchor" href="#blinkande-text" aria-label="Permalink to &quot;Blinkande text&quot;">​</a></h3><p><strong>Exempel: &quot;⚠️ EMERGENCY STOP&quot; blinkar</strong></p><ol><li>Text field</li><li><strong>Animations</strong> → <strong>Flashing</strong></li><li><strong>Flash colors:</strong><ul><li>State 1: Röd text (#FF0000)</li><li>State 2: Svart text (#000000)</li></ul></li><li><strong>Frequency:</strong> 2 Hz</li></ol><div class="warning custom-block"><p class="custom-block-title">Använd blinkning sparsamt</p><p>För mycket blinkande kan distrahera och ge huvudvärk. Använd endast för <strong>kritiska</strong> larm.</p></div><h2 id="kombinerade-animationer" tabindex="-1">Kombinerade animationer <a class="header-anchor" href="#kombinerade-animationer" aria-label="Permalink to &quot;Kombinerade animationer&quot;">​</a></h2><h3 id="exempel-komplett-motor-indikator" tabindex="-1">Exempel: Komplett motor-indikator <a class="header-anchor" href="#exempel-komplett-motor-indikator" aria-label="Permalink to &quot;Exempel: Komplett motor-indikator&quot;">​</a></h3><p>En cirkel som visar motor-status med flera animationer:</p><p><strong>Objekt:</strong> Circle (60x60 px)</p><p><strong>Animationer:</strong></p><ol><li><p><strong>Background color:</strong></p><ul><li><code>Motor_Running = FALSE</code>: Grå</li><li><code>Motor_Running = TRUE</code>: Grön</li><li><code>Motor_Fault = TRUE</code>: Röd</li></ul></li><li><p><strong>Rotation:</strong></p><ul><li>Roterar när <code>Motor_Running = TRUE</code></li><li>Hastighet: 360°/s</li></ul></li><li><p><strong>Flashing:</strong></p><ul><li>Blinkar när <code>Motor_Fault = TRUE</code></li><li>Frekvens: 2 Hz</li></ul></li></ol><p><strong>Resultat:</strong></p><ul><li><strong>Stopped:</strong> Grå cirkel, stillastående</li><li><strong>Running:</strong> Grön cirkel, roterar</li><li><strong>Fault:</strong> Röd cirkel, roterar inte, blinkar</li></ul><h2 id="grafik-och-bilder" tabindex="-1">Grafik och bilder <a class="header-anchor" href="#grafik-och-bilder" aria-label="Permalink to &quot;Grafik och bilder&quot;">​</a></h2><h3 id="importera-bilder" tabindex="-1">Importera bilder <a class="header-anchor" href="#importera-bilder" aria-label="Permalink to &quot;Importera bilder&quot;">​</a></h3><p><strong>Använd bilder för:</strong></p><ul><li>Process-scheman (P&amp;ID)</li><li>Produkt-foton</li><li>Företagslogotyper</li><li>Ikoner</li></ul><p><strong>Importera bild:</strong></p><ol><li><strong>Task cards</strong> → <strong>Graphics</strong></li><li><strong>Import</strong> → Välj bild (PNG, JPG, SVG)</li><li>Dra bild till skärm</li></ol><h3 id="vector-graphics-svg" tabindex="-1">Vector Graphics (SVG) <a class="header-anchor" href="#vector-graphics-svg" aria-label="Permalink to &quot;Vector Graphics (SVG)&quot;">​</a></h3><p><strong>Fördelar:</strong></p><ul><li>Skalar utan kvalitetsförlust</li><li>Kan animeras (färg, storlek)</li><li>Mindre filstorlek</li></ul><p><strong>Använd SVG för:</strong></p><ul><li>Motorer, pumpar, ventiler</li><li>Process-scheman</li><li>Ikoner</li></ul><h3 id="animera-bilder" tabindex="-1">Animera bilder <a class="header-anchor" href="#animera-bilder" aria-label="Permalink to &quot;Animera bilder&quot;">​</a></h3><p><strong>Exempel: Ventil öppen/stängd (två bilder)</strong></p><ol><li>Importera två bilder: <code>valve_open.png</code>, <code>valve_closed.png</code></li><li>Placera båda på samma position</li><li><strong>Visibility animation:</strong><ul><li><code>valve_open.png</code>: Synlig när <code>Valve_Open = TRUE</code></li><li><code>valve_closed.png</code>: Synlig när <code>Valve_Open = FALSE</code></li></ul></li></ol><h2 id="faceplate-ateranvandbara-komponenter" tabindex="-1">Faceplate (Återanvändbara komponenter) <a class="header-anchor" href="#faceplate-ateranvandbara-komponenter" aria-label="Permalink to &quot;Faceplate (Återanvändbara komponenter)&quot;">​</a></h2><h3 id="vad-ar-faceplate" tabindex="-1">Vad är Faceplate? <a class="header-anchor" href="#vad-ar-faceplate" aria-label="Permalink to &quot;Vad är Faceplate?&quot;">​</a></h3><p><strong>Faceplate</strong> är en återanvändbar HMI-komponent (template) med egna animationer och parametrar.</p><p><strong>Exempel:</strong> En &quot;Motor_Faceplate&quot; med:</p><ul><li>Motor-ikon (animerad)</li><li>START/STOP-knappar</li><li>Hastighets-indikator</li><li>Larm-indikator</li></ul><h3 id="skapa-faceplate" tabindex="-1">Skapa Faceplate <a class="header-anchor" href="#skapa-faceplate" aria-label="Permalink to &quot;Skapa Faceplate&quot;">​</a></h3><ol><li><strong>HMI</strong> → <strong>Faceplates</strong> → <strong>Add new faceplate</strong></li><li>Namn: <code>Motor_Control_FP</code></li><li>Designa faceplate (knappar, animationer)</li><li><strong>Lägg till parametrar:</strong><ul><li><code>Motor_Start</code> (BOOL, In/Out)</li><li><code>Motor_Running</code> (BOOL, In)</li><li><code>Motor_Speed</code> (INT, In)</li></ul></li></ol><h3 id="anvanda-faceplate" tabindex="-1">Använda Faceplate <a class="header-anchor" href="#anvanda-faceplate" aria-label="Permalink to &quot;Använda Faceplate&quot;">​</a></h3><ol><li>Dra <code>Motor_Control_FP</code> från <strong>Faceplates</strong> till skärm</li><li><strong>Instance properties:</strong><ul><li><code>Motor_Start</code> → <code>M01_Start</code></li><li><code>Motor_Running</code> → <code>M01_Running</code></li><li><code>Motor_Speed</code> → <code>M01_Speed</code></li></ul></li></ol><p><strong>Fördel:</strong> En faceplate → 10 motorer med samma utseende!</p><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Animationsrekommendationer</p><ol><li><strong>Subtilt, inte distraherande:</strong> Använd mjuka övergångar</li><li><strong>Färgkonsistens:</strong> Grön=OK, Röd=Fel, Gul=Varning överallt</li><li><strong>Prestanda:</strong> Max 50-100 animerade objekt per skärm</li><li><strong>Blinkfrekvens:</strong> 1-2 Hz för larm (inte snabbare)</li><li><strong>Smooth animations:</strong> Använd &quot;Linear&quot; för mjuka rörelser</li><li><strong>Gruppera:</strong> Använd Faceplates för återkommande element</li><li><strong>Test på panel:</strong> Animationer kan se olika ut på faktisk HMI jämfört med simulator</li><li><strong>CPU-belastning:</strong> För många komplexa animationer kan göra HMI långsam</li></ol></div><h2 id="praktiskt-exempel-tanksystem" tabindex="-1">Praktiskt exempel: Tanksystem <a class="header-anchor" href="#praktiskt-exempel-tanksystem" aria-label="Permalink to &quot;Praktiskt exempel: Tanksystem&quot;">​</a></h2><h3 id="process-beskrivning" tabindex="-1">Process-beskrivning <a class="header-anchor" href="#process-beskrivning" aria-label="Permalink to &quot;Process-beskrivning&quot;">​</a></h3><p><strong>System:</strong></p><ul><li>Tank med nivåsensor (0-100%)</li><li>Inloppsventil (öppen/stängd)</li><li>Utloppsventil (öppen/stängd)</li><li>Pump (igång/stopp)</li></ul><h3 id="hmi-design" tabindex="-1">HMI-design <a class="header-anchor" href="#hmi-design" aria-label="Permalink to &quot;HMI-design&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────┐</span></span>
<span class="line"><span>│  Tank System                   │</span></span>
<span class="line"><span>├────────────────────────────────┤</span></span>
<span class="line"><span>│                                │</span></span>
<span class="line"><span>│      [Inlopp ↓]                │  ← Animerad pil (synlig när ventil öppen)</span></span>
<span class="line"><span>│         │                      │</span></span>
<span class="line"><span>│     ┌───────┐                  │</span></span>
<span class="line"><span>│     │▓▓▓▓▓▓▓│  75%             │  ← Tank med animerad nivå</span></span>
<span class="line"><span>│     │▓▓▓▓▓▓▓│                  │</span></span>
<span class="line"><span>│     │░░░░░░░│                  │</span></span>
<span class="line"><span>│     └───┬───┘                  │</span></span>
<span class="line"><span>│         │                      │</span></span>
<span class="line"><span>│      [Utlopp ↓]                │  ← Animerad pil</span></span>
<span class="line"><span>│         │                      │</span></span>
<span class="line"><span>│        🔵 Pump                 │  ← Roterande ikon när igång</span></span>
<span class="line"><span>│                                │</span></span>
<span class="line"><span>│  [Fyll Tank]  [Töm Tank]       │  ← Knappar</span></span>
<span class="line"><span>│                                │</span></span>
<span class="line"><span>└────────────────────────────────┘</span></span></code></pre></div><h3 id="animationer" tabindex="-1">Animationer <a class="header-anchor" href="#animationer" aria-label="Permalink to &quot;Animationer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Objekt</th><th>Animation</th><th>Tagg</th><th>Konfiguration</th></tr></thead><tbody><tr><td><strong>Tank-nivå</strong></td><td>Rectangle height</td><td><code>Tank_Level</code> (0-100%)</td><td>0%=0px, 100%=200px</td></tr><tr><td><strong>Nivå-färg</strong></td><td>Background color</td><td><code>Tank_Level</code></td><td>0-20: Röd, 20-80: Grön, 80-100: Gul</td></tr><tr><td><strong>Inlopps-pil</strong></td><td>Visibility</td><td><code>Valve_Inlet_Open</code></td><td>TRUE=Synlig</td></tr><tr><td><strong>Utlopps-pil</strong></td><td>Visibility</td><td><code>Valve_Outlet_Open</code></td><td>TRUE=Synlig</td></tr><tr><td><strong>Pump-ikon</strong></td><td>Rotation</td><td><code>Pump_Running</code></td><td>360°/s när TRUE</td></tr><tr><td><strong>Pump-färg</strong></td><td>Background</td><td><code>Pump_Running</code></td><td>TRUE=Grön, FALSE=Grå</td></tr><tr><td><strong>Nivå-text</strong></td><td>Text</td><td><code>Tank_Level</code></td><td>&quot;75 %&quot;</td></tr></tbody></table><h3 id="plc-taggar" tabindex="-1">PLC-taggar <a class="header-anchor" href="#plc-taggar" aria-label="Permalink to &quot;PLC-taggar&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tank_Level : REAL := 0.0;           // 0-100%</span></span>
<span class="line"><span>Valve_Inlet_Open : BOOL := FALSE;</span></span>
<span class="line"><span>Valve_Outlet_Open : BOOL := FALSE;</span></span>
<span class="line"><span>Pump_Running : BOOL := FALSE;</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=wincc%20animation" target="_blank" rel="noreferrer">Siemens: WinCC Animation dokumentation (sökresultat)</a></li><li><a href="https://www.youtube.com/watch?v=ZP8i3VoS1_w" target="_blank" rel="noreferrer">Video: Creating Dynamic HMI Objects</a></li><li><a href="https://www.youtube.com/watch?v=x_dN8cPkYnM" target="_blank" rel="noreferrer">Video: Faceplates and Reusable Components</a></li><li><a href="https://www.youtube.com/watch?v=lKjM8mQ6rY8" target="_blank" rel="noreferrer">Video: Process Graphics in WinCC</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./skarmbilder.html">Skärmbilder och layout</a></li><li><a href="./knappar-indikatorer.html">Knappar och indikatorer</a></li><li><a href="./../05-taggar/koppling-plc-hmi.html">Koppling PLC↔HMI</a></li></ul>`,124)])])}const m=n(i,[["render",o]]);export{h as __pageData,m as default};
